script:
(function () {
  'use strict';
  // Taxable account vs tax-deferred account, same out-of-pocket savings.
  // Growth: monthly factor (1 + r)^(1/12), so a balance with no contributions earns exactly r a year.
  // Taxable account: each year, the chosen share of that year's earnings (interest, dividends,
  //   fund distributions) is taxed at the current tax rate and the rest of it is reinvested and
  //   added to cost basis. The untaxed share builds up as unrealized gain, taxed at the capital
  //   gains rate when sold. Contributions are after-tax and add to basis.
  // Tax-deferred account: nothing is taxed while invested. Deductible (traditional 401(k)/IRA):
  //   each contribution is grossed up to C / (1 - current rate), so it costs the same take-home pay
  //   as C in the taxable account, and every dollar withdrawn is taxed at the retirement rate.
  //   Non-deductible (non-deductible IRA, deferred annuity): it receives C, and only the growth
  //   is taxed at withdrawal (pro rata share of each withdrawal).
  // Withdrawals (optional): a level after-tax amount at the start of each year, found by bisection,
  //   that empties each account over the chosen years; the balance keeps growing (and the taxable
  //   account keeps paying yearly tax, at the retirement rate) while it is drawn down.
  // Verified (Node scratch test, tests/td.test.js):
  //   $10,000 lump sum, 7%, 30 years, 24% now and later, 100% taxed yearly, deductible:
  //     taxable = 10,000 x 1.0532^30 = $47,350.60; tax-deferred = 13,157.89 x 1.07^30 x 0.76 =
  //     10,000 x 1.07^30 = $76,122.55 (the deductible account behaves like a tax-free one when the
  //     rate is the same now and later).
  //   0% tax everywhere: both accounts equal the plain compound value ($76,122.55).
  //   0% taxed yearly, 15% capital gains: taxable after sale = 76,122.55 - 0.15 x 66,122.55 =
  //     $66,204.17.
  //   Non-deductible, 22% at withdrawal: 76,122.55 - 0.22 x 66,122.55 = $61,575.59.
  //   $500 at the end of each month, 0% tax, 7%, 25 years = 500 x ((1.07^(1/12))^300 - 1) /
  //     (1.07^(1/12) - 1) = $391,520.94 (matches the annuity formula).
  //   Withdrawal phase, deductible, 22%: level after-tax income = 0.78 x B x r / ((1 - 1.07^-n) x 1.07)
  //     (annuity due): $100,000 at 7% for 1 year, then 20 years -> $7,362.65 a year.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function num(id) {
    var el = document.getElementById(id);
    var v = parseFloat(el.value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }

  // Builds both accounts through the saving years.
  function accumulate(o) {
    var gm = Math.pow(1 + o.r, 1 / 12) - 1;
    var gross = o.deductible ? 1 / (1 - o.tNow) : 1;
    var every = 12 / o.perYear;
    var T = { bal: o.start, basis: o.start };
    var D = { bal: o.start * gross, basis: o.deductible ? 0 : o.start };
    var paid = 0, outOfPocket = o.start, rows = [];
    for (var y = 1; y <= o.years; y++) {
      var earned = 0;
      for (var m = 1; m <= 12; m++) {
        var e = T.bal * gm;
        T.bal += e;
        earned += e;
        D.bal += D.bal * gm;
        if (m % every === 0) {
          T.bal += o.contrib; T.basis += o.contrib;
          D.bal += o.contrib * gross;
          if (!o.deductible) D.basis += o.contrib;
          outOfPocket += o.contrib;
        }
      }
      var taxedPart = Math.max(0, earned) * o.share;
      var tax = taxedPart * o.tNow;
      T.bal -= tax;
      T.basis += taxedPart - tax;
      paid += tax;
      rows.push({ year: y, tBal: T.bal, tax: tax, dBal: D.bal, dAfter: afterTaxD(D, o) });
    }
    return { T: T, D: D, paid: paid, outOfPocket: outOfPocket, rows: rows };
  }

  function afterTaxT(T, o) { return T.bal - o.tCg * Math.max(0, T.bal - T.basis); }
  function afterTaxD(D, o) { return D.bal - o.tRet * Math.max(0, D.bal - D.basis); }

  // Final balance after paying a level after-tax amount n at the start of each year.
  function drawDown(acct, kind, n, o) {
    var bal = acct.bal, basis = acct.basis;
    for (var y = 0; y < o.wYears; y++) {
      if (bal <= 0) return -1;
      var f = Math.max(0, (bal - basis) / bal);
      var rate = kind === 'T' ? o.tCg * f : o.tRet * f;
      var gross = n / (1 - rate);
      if (gross > bal + 1e-9) return -1;
      basis -= basis * (gross / bal);
      bal -= gross;
      var growth = bal * o.r;
      bal += growth;
      if (kind === 'T') {
        var taxedPart = growth * o.share, tax = taxedPart * o.tRet;
        bal -= tax;
        basis += taxedPart - tax;
      }
    }
    return bal;
  }

  function levelIncome(acct, kind, o) {
    if (o.wYears < 1 || acct.bal <= 0) return 0;
    var lo = 0, hi = acct.bal * Math.pow(1 + o.r, o.wYears);
    for (var i = 0; i < 100; i++) {
      var mid = (lo + hi) / 2;
      if (drawDown(acct, kind, mid, o) >= 0) lo = mid; else hi = mid;
    }
    return lo;
  }

  function clearRows(id) {
    var body = document.getElementById(id);
    while (body.firstChild) body.removeChild(body.firstChild);
    return body;
  }

  function update() {
    var o = {
      start: num('tdStart'), contrib: num('tdContrib'), perYear: parseInt(document.getElementById('tdFreq').value, 10),
      years: Math.round(num('tdYears')), r: num('tdReturn') / 100, tNow: num('tdTaxNow') / 100,
      tRet: num('tdTaxRet') / 100, share: num('tdShare') / 100, tCg: num('tdCg') / 100,
      wYears: Math.round(num('tdWYears')), deductible: document.getElementById('tdDeductible').checked
    };
    var error = document.getElementById('tdError');
    var msg = '';
    if ([o.start, o.contrib, o.years, o.r, o.tNow, o.tRet, o.share, o.tCg, o.wYears].some(isNaN)) msg = 'Fill in every field with a number.';
    else if (o.start < 0 || o.contrib < 0) msg = 'Amounts cannot be negative.';
    else if (o.years < 1 || o.years > 60) msg = 'Enter 1 to 60 years of saving.';
    else if (o.r < 0 || o.r > 0.3) msg = 'Enter a rate of return from 0 to 30%.';
    else if ([o.tNow, o.tRet, o.tCg].some(function (t) { return t < 0 || t > 0.6; })) msg = 'Enter tax rates from 0 to 60%.';
    else if (o.share < 0 || o.share > 1) msg = 'The share taxed each year must be 0 to 100%.';
    else if (o.wYears < 0 || o.wYears > 50) msg = 'Enter 0 to 50 years of withdrawals.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) {
      ['tdAdvantage', 'tdTaxableAfter', 'tdDeferredAfter', 'tdTaxableBal', 'tdDeferredBal', 'tdTaxesPaid',
       'tdTaxableExit', 'tdDeferredExit', 'tdOutOfPocket', 'tdTaxableIncome', 'tdDeferredIncome'].forEach(function (id) { set(id, '–'); });
      document.getElementById('tdVerdict').hidden = true;
      clearRows('tdSchedule');
      return;
    }
    var a = accumulate(o);
    var tAfter = afterTaxT(a.T, o), dAfter = afterTaxD(a.D, o), diff = dAfter - tAfter;
    set('tdAdvantage', (diff < 0 ? '−' : '') + money.format(Math.abs(diff)));
    set('tdAdvantageLabel', diff >= 0 ? 'Tax-deferred comes out ahead by' : 'Taxable comes out ahead by');
    set('tdTaxableAfter', money.format(tAfter));
    set('tdDeferredAfter', money.format(dAfter));
    set('tdTaxableBal', money.format(a.T.bal));
    set('tdDeferredBal', money.format(a.D.bal));
    set('tdTaxesPaid', money.format(a.paid));
    set('tdTaxableExit', money.format(a.T.bal - tAfter));
    set('tdDeferredExit', money.format(a.D.bal - dAfter));
    set('tdOutOfPocket', money.format(a.outOfPocket));
    if (o.wYears > 0) {
      var ti = levelIncome(a.T, 'T', o), di = levelIncome(a.D, 'D', o);
      set('tdTaxableIncome', money.format(ti) + ' a year');
      set('tdDeferredIncome', money.format(di) + ' a year');
    } else {
      set('tdTaxableIncome', 'Not used');
      set('tdDeferredIncome', 'Not used');
    }
    var verdict = document.getElementById('tdVerdict');
    verdict.hidden = false;
    var pct = tAfter > 0 ? Math.abs(diff) / tAfter * 100 : 0;
    if (Math.abs(diff) < 0.5) verdict.textContent = 'Both accounts leave you with the same amount after tax.';
    else verdict.textContent = (diff > 0 ? 'The tax-deferred account' : 'The taxable account') + ' leaves you ' +
      money.format(Math.abs(diff)) + ' more after tax (' + pct.toFixed(1) + '% more) if you cash out after ' + o.years +
      (o.years === 1 ? ' year.' : ' years.');
    var body = clearRows('tdSchedule');
    a.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      [String(row.year), money.format(row.tBal), money.format(row.tax), money.format(row.dBal), money.format(row.dAfter)].forEach(function (t) {
        var td = document.createElement('td');
        td.textContent = t;
        tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('tdForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
